        locais, nao_usados = arquivos_locais(leitor, moodle)
        for a in locais:
            a["sha"] = sha_b(leitor.le(a["caminho"]))
        por_nome, por_rel = {}, {a["rel"]: a for a in locais}
        for a in locais:
            por_nome.setdefault((a["nome"], a["tamanho"]), []).append(a)
        inv, inv_sha = carrega_inventario(fonte)
